const lead = $input.first().json;
const followUpCount = lead.follow_up_count || 0;
const tier = lead.qualification_tier || 'LUKEWARM';
const daysSinceCreated = Math.floor(
  (new Date() - new Date(lead.created_at)) / (1000 * 60 * 60 * 24)
);

// Determine follow-up strategy based on count and tier
const strategies = {
  0: {
    channel: 'multi',
    delay_hours: 0,
    template: 'initial_contact',
    subject: 'Your Insurance Quote Request'
  },
  1: {
    channel: 'email',
    delay_hours: 24,
    template: 'value_proposition',
    subject: 'Here\'s How We Can Save You Money'
  },
  2: {
    channel: 'sms',
    delay_hours: 48,
    template: 'quick_check_in',
    subject: null
  },
  3: {
    channel: 'email',
    delay_hours: 96,
    template: 'educational_content',
    subject: 'Important: Understanding Your Coverage Options'
  },
  4: {
    channel: 'sms',
    delay_hours: 168, // 7 days
    template: 'last_chance',
    subject: null
  },
  5: {
    channel: 'email',
    delay_hours: 240, // 10 days
    template: 'breakup_email',
    subject: 'Should I close your file?'
  },
  6: {
    channel: 'sms',
    delay_hours: 336, // 14 days
    template: 'final_reach_out',
    subject: null
  }
};

const strategy = strategies[followUpCount] || strategies[6];

// Hot leads get more aggressive follow-up
if (tier === 'HOT' && followUpCount < 3) {
  strategy.delay_hours = Math.floor(strategy.delay_hours / 2);
}

// Calculate next follow-up time
const nextFollowUp = new Date();
nextFollowUp.setHours(nextFollowUp.getHours() + (strategy.delay_hours || 24));

// Determine if we should stop following up
const shouldStopFollowUp = followUpCount >= 7 || daysSinceCreated > 21;

return {
  json: {
    ...lead,
    follow_up_strategy: strategy,
    next_follow_up_at: nextFollowUp.toISOString(),
    should_stop_follow_up: shouldStopFollowUp,
    days_since_created: daysSinceCreated,
    current_follow_up_number: followUpCount + 1
  }
};

