const lead = $input.first().json;
const aiMessage = $input.last().json;

// Parse AI response
let messages;
try {
  const content = aiMessage.choices[0].message.content;
  messages = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  // Fallback message
  messages = {
    email_subject: `Following up on your ${lead.coverage_type} inquiry`,
    email_body: `Hi ${lead.first_name},\n\nI wanted to follow up on your recent inquiry about ${lead.coverage_type} coverage. I have some excellent options that could work well for your situation.\n\nWhen would be a good time for a quick 15-minute call?\n\nBest regards,\n${process.env.AGENT_NAME}`,
    sms_message: `Hi ${lead.first_name}, following up on your ${lead.coverage_type} inquiry. Have time for a quick call? - ${process.env.AGENT_NAME}`,
    personalization_notes: 'Generic fallback message'
  };
}

return {
  json: {
    ...lead,
    generated_messages: messages
  }
};

